/** Self-check: npx tsx src/lib/stitchTemplates.ts */
if (typeof process !== 'undefined' && process.argv?.[1]?.endsWith('stitchTemplates.ts')) {
  const { renderGuestPage, docError, DOC_MAX } = await import('./guestPage.js');
  const { templateContentError } = await import('./pageTemplates.js');
  const assert = (c: unknown, m: string) => { if (!c) { console.error('FAIL', m); process.exit(1); } };
  assert(STITCH_TEMPLATES.length === 16 && new Set(STITCH_TEMPLATES.map(t => t.id)).size === 16, 'sixteen unique templates');
  assert(new Set(STITCH_TEMPLATES.map(t => t.group)).size === 4, 'four groups');
  for (const t of STITCH_TEMPLATES) {
    const d = t.content.doc;
    assert(!docError(d) && !templateContentError(t.content), `${t.id} passes docError and templateContentError`);
    assert(d.html.length + d.css.length < DOC_MAX && JSON.stringify(t.content).length < DOC_MAX + 5000, `${t.id} fits the cap`);
    const r = renderGuestPage({ qr_type: 'page', slug: 'abcdefg', title: t.name, content_data: t.content }, 'en', 'https://s.lk/abcdefg') as any;
    assert(r?.kind === 'html' && r.body.includes('<style>') && !/<script|\son[a-z]+=|9:41/.test(r.body), `${t.id} renders without scripts or the fake status bar`);
    assert(!/https?:\/\/(?!scnr\.tharkak\.com|fonts\.|cdnjs\.|www\.w3\.org|wa\.me|instagram\.com|maps\.google\.com|whatsapp\.com)[^"' )]+\.(png|jpe?g|webp)/i.test(d.html + d.css), `${t.id} has no hotlinked images`);
  }
  console.log('stitchTemplates self-check ok');
}
